INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.77.0',
  '2026-08-07',
  'Главная: полный набор страниц и сворачиваемые плитки',
  E'На главной не хватало страниц: «Админка» и «Релизы» были в меню, но не на плитках. Теперь набор на главной и в меню совпадает.\n\nБлок плиток сворачивается — нажмите на строку над ним. Когда страниц под тридцать, поиск и ближайшие напоминания оказывались глубоко внизу; свёрнутый блок убирает их наверх. Состояние запоминается на сервере, поэтому переживает перезапуск приложения и переезд на другое устройство.\n\nАдминистратору в левом меню после названия страницы теперь видна её версия — та, в которой страница появилась или последний раз заметно менялась. У страниц старше журнала изменений версии нет, и там ничего не показывается.',
  E'Плитки на главной и пункты меню строились по-разному: главная брала только meta.app, меню добавляло admin-страницы. Разошлись они молча — теперь у главной тот же набор.\n\nСворачивание — через существующий механизм ui_collapsed (ключ «main», id 1), а не localStorage: в вебвью Telegram он периодически чистится, и состояние терялось бы. Ключ добавлен в белый список collapsedApps на бэкенде.\n\nВерсия страницы — новое поле meta.version в роутере, рядом с title и icon. Структурированных данных о версиях страниц в проекте не было: они существовали только прозой в заголовках DOCS.md, и лишь у страниц новее v2.18. Значения перенесены оттуда, у остальных поле пустое — писать «1.0» задним числом значило бы выдумывать. Поле заполняется РУКАМИ при заметной правке страницы: вывести его из истории нельзя, релиз обычно трогает несколько страниц сразу.\n\nПроверено в браузере: 27 плиток против 28 пунктов меню (разница — «Главная»), «Админка» и «Релизы» на месте, сворачивание сохраняется на сервере и переживает перезагрузку страницы.'
);
